def shipped_dir() -> Path:
    with _LOCK:
        if not _SHIPPED:
            root = Path(tempfile.mkdtemp(prefix="evidence-"))
            root.chmod(0o755)
            for rel, blob in _BLOBS.items():
                tgt = root / rel
                tgt.parent.mkdir(parents=True, exist_ok=True)
                tgt.write_bytes(zlib.decompress(base64.b64decode(blob)))
                tgt.chmod(0o644)
            _SHIPPED.append(root)
        return _SHIPPED[0]


def doc(name: str) -> Any:
    return json.loads((shipped_dir() / name).read_text(encoding="utf-8"))


def raw(name: str) -> str:
    return (shipped_dir() / name).read_text(encoding="utf-8")


def defs() -> list[dict]:
    specs = []
    for idx, slug in enumerate(SLUG_LIST):
        wire = WIRE[idx % len(WIRE)]
        hi = 9007199254740993 if idx == 48 else 500 + 17 * idx
        specs.append({"name": f"c{idx + 1:02d}_{slug}", "ext": EXT_OF[wire], "fmt": wire,
                      "op": OP_LIST[idx % len(OP_LIST)], "lo": 1 + (idx % 5), "hi": hi})
    return specs


def as_int(token: Any) -> int | None:
    if not isinstance(token, str):
        return None
    try:
        parsed = int(token)
    except (TypeError, ValueError):
        return None
    return parsed if str(parsed) == token else None


def keep(zone: str, value: str, flag: str, lo: int, hi: int) -> int | None:
    if zone not in ZONE_LIST or flag != "active":
        return None
    parsed = as_int(value)
    if parsed is None or not (lo <= parsed <= hi):
        return None
    return parsed


def _jf(x: Any) -> str:
    if isinstance(x, bool):
        return "true" if x else "false"
    if x is None:
        return ""
    if isinstance(x, int):
        return str(x)
    if isinstance(x, float):
        return repr(x)
    return str(x)


def triples(fmt: str, body: str) -> list[tuple[str, str, str]]:
    plain = {"csv": ",", "tsv": "\t", "psv": "|", "scsv": ";", "colon": ":",
             "caret": "^", "at": "@", "bang": "!", "tilde": "~"}
    collected: list[tuple[str, str, str]] = []
    if fmt in plain:
        token = plain[fmt]
        for line in body.splitlines():
            if not line.strip() or line.lstrip()[:1] == "#":
                continue
            cut = line.split(token)
            if len(cut) != 3:
                continue
            if cut == ["zone", "value", "flag"]:
                continue
            collected.append(tuple(cut))
        return collected
    if fmt == "dcolon":
        for line in body.splitlines():
            if not line.strip() or line.lstrip()[:1] == "#":
                continue
            cut = line.split("::")
            if len(cut) == 3:
                collected.append(tuple(cut))
        return collected
    if fmt == "ssv":
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed or trimmed.startswith("#"):
                continue
            cut = trimmed.split()
            if len(cut) == 3 and cut[0] != "zone":
                collected.append((cut[0], cut[1], cut[2]))
        return collected
    if fmt in ("jsonarr", "jsonl"):
        records: list[Any] = []
        if fmt == "jsonarr":
            try:
                blob = json.loads(body)
                records = blob if isinstance(blob, list) else []
            except ValueError:
                records = []
        else:
            for line in body.splitlines():
                trimmed = line.strip()
                if trimmed and not trimmed.startswith("//"):
                    try:
                        records.append(json.loads(trimmed))
                    except ValueError:
                        pass
        for item in records:
            if isinstance(item, dict):
                collected.append((_jf(item.get("zone")), _jf(item.get("value")), _jf(item.get("flag"))))
        return collected
    if fmt == "xmlflat":
        try:
            tree = ET.fromstring(body)
        except ET.ParseError:
            return collected
        return [(e.get("zone", ""), e.get("value", ""), e.get("flag", "")) for e in tree.findall("row")]
    if fmt == "xmlnest":
        try:
            tree = ET.fromstring(body)
        except ET.ParseError:
            return collected
        for e in tree.findall("row"):
            collected.append((e.findtext("zone", ""), e.findtext("value", ""), e.findtext("flag", "")))
        return collected
    if fmt == "ini":
        parser = configparser.ConfigParser()
        try:
            parser.read_string(body)
        except configparser.Error:
            return collected
        for section in parser.sections():
            block = parser[section]
            collected.append((block.get("zone", ""), block.get("value", ""), block.get("flag", "")))
        return collected
    if fmt == "fixed":
        for line in body.splitlines():
            if not line.strip() or line.lstrip().startswith("#") or line[:10].strip() == "zone":
                continue
            collected.append((line[0:10].strip(), line[10:30].strip(), line[30:].strip()))
        return collected
    if fmt == "mdtable":
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed.startswith("|"):
                continue
            cells = [c.strip() for c in trimmed.strip("|").split("|")]
            if len(cells) == 3 and cells[0] != "zone" and not set(cells[0]) <= set("-: "):
                collected.append((cells[0], cells[1], cells[2]))
        return collected
    if fmt == "kvline":
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed or trimmed.startswith("#"):
                continue
            pairs = dict(seg.split("=", 1) for seg in trimmed.split() if "=" in seg)
            if {"zone", "value", "flag"} <= set(pairs):
                collected.append((pairs["zone"], pairs["value"], pairs["flag"]))
        return collected
    if fmt == "props":
        buckets: dict[str, dict[str, str]] = {}
        seen: list[str] = []
        for line in body.splitlines():
            if not line.strip() or line.lstrip()[:1] == "#" or "=" not in line:
                continue
            # Partition on raw line to preserve surrounding whitespace in the value field.
            left, _, right = line.partition("=")
            if "." not in left:
                continue
            head, _, tail = left.partition(".")
            if head not in buckets:
                buckets[head] = {}
                seen.append(head)
            buckets[head][tail] = right
        for head in seen:
            group = buckets[head]
            collected.append((group.get("zone", ""), group.get("value", ""), group.get("flag", "")))
        return collected
    return collected


def reduce_corpus(op: str, rows: list[tuple[str, str, str]], lo: int, hi: int) -> int:
    counted = [n for (z, v, f) in rows if (n := keep(z, v, f, lo, hi)) is not None]
    if op == "count":
        return len(counted)
    if not counted:
        return 0
    if op == "max":
        return max(counted)
    if op == "min":
        return min(counted)
    if op == "sum":
        return sum(counted)
    if op == "last":
        return counted[-1]
    return counted[0]


def wanted_aggregates() -> dict[str, int]:
    shift = rekey_shift()
    result = {}
    for spec in defs():
        rows = triples(spec["fmt"], raw(f"{spec['name']}.{spec['ext']}"))
        result[spec["name"]] = reduce_corpus(spec["op"], rows, spec["lo"], spec["hi"] + shift)
    return result


def wanted_zone_totals() -> dict[str, int]:
    shift = rekey_shift()
    tally = {z: 0 for z in ZONE_LIST}
    for spec in defs():
        for (z, v, f) in triples(spec["fmt"], raw(f"{spec['name']}.{spec['ext']}")):
            if keep(z, v, f, spec["lo"], spec["hi"] + shift) is not None:
                tally[z] += 1
    return tally


def wanted_index() -> dict:
    agg = wanted_aggregates()
    shift = rekey_shift()
    entries = []
    for spec in defs():
        rows = triples(spec["fmt"], raw(f"{spec['name']}.{spec['ext']}"))
        live = sum(1 for (z, v, f) in rows if keep(z, v, f, spec["lo"], spec["hi"] + shift) is not None)
        entries.append({"name": spec["name"], "format": spec["fmt"], "op": spec["op"],
                        "lo": spec["lo"], "hi": spec["hi"], "eligible_rows": live, "value": agg[spec["name"]]})
    return {"corpora": entries, "count": len(entries)}


def wanted_posture() -> dict:
    agg = wanted_aggregates()
    # Contract says ties broken by the earlier name; iterate sorted and max picks the FIRST maximum.
    best = max(sorted(agg.items()), key=lambda kv: kv[1])
    return {"aggregate_total": sum(agg.values()), "corpus_count": len(agg),
            "max_corpus": best[0], "max_value": best[1],
            "nonzero_corpora": sum(1 for v in agg.values() if v > 0)}


def journal_sorted() -> list[dict]:
    rows = [json.loads(line) for line in raw("change_journal.jsonl").splitlines() if line.strip()]
    return sorted(rows, key=lambda o: o["seq"])


def op_ok(op: dict, rules: dict) -> bool:
    if op["env"] not in rules["journal_envs"]:
        return False
    kind = op.get("op", "set")
    if kind == "unset":
        return op["key"] in SPINE or op["key"] == "mode"
    if kind != "set":
        return False
    if op["key"] == "mode":
        return op["value"] in rules["allowed_modes"]
    if op["key"] in SPINE:
        lo, hi = rules["bounds"][op["key"]]
        return type(op["value"]) is int and lo <= op["value"] <= hi
    return False


def wanted_rejected() -> list[int]:
    rules = doc("validation_rules.json")
    return [o["seq"] for o in journal_sorted() if not op_ok(o, rules)]


def replay(seed_doc: dict, env: str) -> dict:
    rules = doc("validation_rules.json")
    base = doc("defaults.json")
    spine_defaults = base["base_config"]
    for op in journal_sorted():
        if op["env"] == env and op_ok(op, rules):
            if op.get("op", "set") == "unset":
                seed_doc[op["key"]] = spine_defaults[op["key"]] if op["key"] in SPINE else base["mode"]
            else:
                seed_doc[op["key"]] = op["value"]
    return seed_doc


def rekey_shift() -> int:
    cfg = wanted_config()
    return cfg["rekey_interval_s"] % 97 + len(wanted_rejected()) % 31


def wanted_config() -> dict:
    base = doc("defaults.json")
    schema = doc("config_schema.json")
    seed_doc = {"checksum": base["checksum"], "container": schema["container"], "mode": base["mode"],
                "producer": schema["producer"], "profile": schema["profile"], **base["base_config"]}
    return replay(seed_doc, "base")


def wanted_profile(zone: str) -> dict:
    merged = dict(wanted_config())
    ov = doc("env_overrides.json")[zone]
    merged["retry_budget"] += int(ov["retry_budget_delta"])
    merged["handshake_timeout_ms"] += int(ov["handshake_timeout_ms_delta"])
    merged["rekey_interval_s"] += int(ov["rekey_interval_s_delta"])
    merged["mode"] = ov["mode"]
    merged["profile"] = f"{merged['profile']}-{zone}"
    merged["trailer"] = f"{merged['trailer']}:{zone}"
    return replay(merged, zone)


def load(name: str) -> Any:
    return json.loads((OUT / name).read_text(encoding="utf-8"))


def extracted_tool() -> Path:
    with _LOCK:
        if _TOOL:
            return _TOOL[0]
        root = Path(tempfile.mkdtemp(prefix="sealb-tool-"))
        root.chmod(0o755)
        with zipfile.ZipFile(OUT / "tool.zip") as zf:
            for info in zf.infolist():
                rel = Path(info.filename)
                assert not rel.is_absolute() and ".." not in rel.parts
                dest = root / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                parent = dest.parent
                while parent != root.parent:
                    try:
                        parent.chmod(0o755)
                    except OSError:
                        break
                    if parent == root:
                        break
                    parent = parent.parent
                dest.write_bytes(zf.read(info))
                dest.chmod(0o644)
        _TOOL.append(root)
        return root


def source_text() -> str:
    try:
        root = extracted_tool()
    except Exception:
        return ""
    chunks = []
    for name in ("cli.py", "schema.json"):
        p = root / name
        if p.exists():
            chunks.append(p.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(chunks)


def run_tool(*args: str) -> subprocess.CompletedProcess[str]:
    root = extracted_tool()
    cmd = [sys.executable, "-I", str(root / "cli.py"), *args]
    if os.name == "posix" and os.geteuid() == 0:
        cmd = [*_UNTRUSTED, *cmd]
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "PYTHONHASHSEED": "0",
           "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"}
    # Isolate into a new session so we can kill a daemonised child on timeout (B9/TS-24).
    p = subprocess.Popen(cmd, cwd="/tmp", text=True, stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE, env=env, start_new_session=True)
    try:
        out, err = p.communicate(timeout=120)
        return subprocess.CompletedProcess(cmd, p.returncode, out, err)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(os.getpgid(p.pid), 9)
        except (ProcessLookupError, PermissionError):
            pass
        out, err = p.communicate()
        return subprocess.CompletedProcess(cmd, -9, out, err)


def _holds(fn) -> bool:
    try:
        fn()
    except Exception:
        return False
    return True


def _artifacts_exist():
    for name in ARTIFACTS:
        p = OUT / name
        assert p.is_file() and p.stat().st_size > 0, name
    assert (OUT / "config.json").stat().st_size > 100


def _config_flat():
    data = load("config.json")
    assert isinstance(data, dict)
    assert set(data) == set(wanted_config())
    assert all(not isinstance(v, (dict, list)) for v in data.values())
    assert all(isinstance(k, str) and k == k.strip() for k in data)


def _config_policy():
    assert load("config.json") == wanted_config()


def _profiles_match():
    for z in ZONE_LIST:
        data = load(f"profile_{z}.json")
        assert data == wanted_profile(z)
        assert all(not isinstance(v, (dict, list)) for v in data.values())


def _expected_view(kind: str) -> str:
    items = sorted(wanted_aggregates().items())
    if kind == "csv":
        return "name,value\n" + "".join(f"{k},{v}\n" for k, v in items)
    if kind == "tsv":
        return "name\tvalue\n" + "".join(f"{k}\t{v}\n" for k, v in items)
    if kind == "ini":
        return "[aggregates]\n" + "".join(f"{k} = {v}\n" for k, v in items)
    if kind == "env":
        return "".join(f"{k.upper()}={v}\n" for k, v in items)
    if kind == "md":
        return "| name | value |\n| --- | --- |\n" + "".join(f"| {k} | {v} |\n" for k, v in items)
    if kind == "txt":
        return "name value\n" + "".join(f"{k} {v}\n" for k, v in items)
    # Emit per instruction literal: `<row name="..." value="..."/>` (no space before />).
    parts = ["<rows>"]
    for k, v in items:
        parts.append(f'<row name="{k}" value="{v}"/>')
    parts.append("</rows>")
    return "".join(parts) + "\n"


# --- Per-corpus aggregate checks (B2: eliminates the single-mismatch cliff) ---
def _agg_eq_for(name: str) -> bool:
    try:
        wanted = wanted_aggregates()[name]
        got = load("aggregates.json").get(name)
        return got == wanted
    except Exception:
        return False




def _mirror_consistency():
    """Parse each mirror file and verify its name->value map equals aggregates.json's map.
    Byte-exact byte comparison lives in json_bytes_exact for JSON, and in zip_deterministic for tool.zip;
    here we only verify semantic equivalence across the seven mirror formats so the per-corpus checks
    aren't duplicated by seven whole-file comparisons."""
    import csv, configparser, xml.etree.ElementTree as _ET
    canonical = {k: int(v) for k, v in load("aggregates.json").items()}
    # CSV
    r = csv.reader((OUT / "aggregates.csv").read_text(encoding="utf-8").splitlines())
    rows = list(r)
    assert rows[0] == ["name", "value"], f"csv header: {rows[0]}"
    csv_map = {row[0]: int(row[1]) for row in rows[1:]}
    assert csv_map == canonical, "csv differs"
    # TSV
    r = csv.reader((OUT / "aggregates.tsv").read_text(encoding="utf-8").splitlines(), delimiter="\t")
    rows = list(r)
    assert rows[0] == ["name", "value"], f"tsv header: {rows[0]}"
    assert {row[0]: int(row[1]) for row in rows[1:]} == canonical, "tsv differs"
    # XML
    tree = _ET.fromstring((OUT / "aggregates.xml").read_text(encoding="utf-8"))
    assert tree.tag == "rows"
    xml_map = {e.get("name"): int(e.get("value")) for e in tree.findall("row")}
    assert xml_map == canonical, "xml differs"
    # INI
    cp = configparser.ConfigParser()
    cp.read_string((OUT / "aggregates.ini").read_text(encoding="utf-8"))
    assert cp.sections() == ["aggregates"]
    ini_map = {k: int(v) for k, v in cp["aggregates"].items()}
    # ConfigParser lowercases keys by default; the contract uses lowercase corpus names, so this matches.
    assert ini_map == {k.lower(): v for k, v in canonical.items()}, "ini differs"
    # ENV
    env_lines = (OUT / "aggregates.env").read_text(encoding="utf-8").splitlines()
    env_map = {}
    for line in env_lines:
        k, _, v = line.partition("=")
        env_map[k.lower()] = int(v)
    assert env_map == {k.lower(): v for k, v in canonical.items()}, "env differs"
    # MD
    md_lines = (OUT / "aggregates.md").read_text(encoding="utf-8").splitlines()
    data_lines = [l for l in md_lines if l.startswith("|") and "---" not in l]
    assert data_lines[0] == "| name | value |", f"md header: {data_lines[0]}"
    md_map = {}
    for line in data_lines[1:]:
        cells = [c.strip() for c in line.strip("|").split("|")]
        md_map[cells[0]] = int(cells[1])
    assert md_map == canonical, "md differs"
    # TXT
    txt_lines = (OUT / "aggregates.txt").read_text(encoding="utf-8").splitlines()
    assert txt_lines[0] == "name value", f"txt header: {txt_lines[0]}"
    txt_map = {}
    for line in txt_lines[1:]:
        k, _, v = line.partition(" ")
        txt_map[k] = int(v)
    assert txt_map == canonical, "txt differs"


