def _validation_report():
    data = load("validation_report.json")
    checks = data["checks"]
    # Instruction L15: ok is true iff every nested check is true and every integer check matches.
    # Boolean checks must be exactly True; integer checks must match the other artifacts byte-for-byte.
    assert data["ok"] is True
    assert checks["all_artifacts_present"] is True
    assert checks["config_matches_policy"] is True
    assert checks["config_scalar_flat"] is True
    assert checks["command_failures"] == 0                       # integer
    assert checks["rejected_ops"] == len(wanted_rejected())      # integer (count), per instruction's "integer check" rule
    assert set(checks["profiles"]) == set(ZONE_LIST)
    for z in ZONE_LIST:
        # profiles[z] carries scalar_flat and trailer; both booleans per instruction L15.
        assert checks["profiles"][z]["scalar_flat"] is True
        assert checks["profiles"][z]["trailer"] is True
    assert checks["corpus_count"] == 50                          # integer
    assert checks["aggregate_total"] == sum(wanted_aggregates().values())


def _summary():
    data = load("summary.json")
    inputs = sorted(p.name for p in shipped_dir().iterdir() if p.is_file())
    assert data["tool"] == "sealb-ctl"
    assert data["profile_tag"] == wanted_config()["profile"]
    assert data["trailer"] == TRAILER
    assert data["profiles"] == ZONE_LIST
    assert data["artifacts"] == sorted(ARTIFACTS)
    assert data["artifact_count"] == len(ARTIFACTS)
    assert data["inputs"] == inputs
    assert data["input_count"] == len(inputs)
    assert data["corpus_count"] == 50
    assert data["aggregate_total"] == sum(wanted_aggregates().values())


def _report_transcript():
    report = load("report.json")
    commands = report["commands"]
    assert report["ok"] is True and report["tool"] == "sealb-ctl"
    assert isinstance(commands, list) and len(commands) >= 1
    assert all(item.get("returncode") == 0 for item in commands)


def _report_digest():
    report = load("report.json")
    assert report["config_sha256"] == hashlib.sha256((OUT / "config.json").read_bytes()).hexdigest()
    assert report["trailer"] == TRAILER
    assert "generated_at" not in report and "timestamp" not in report


def _manifest():
    raw = (OUT / "manifest.sha256").read_bytes()
    # Instruction L19: names in sorted order, single trailing newline.
    assert raw.endswith(b"\n"), "manifest.sha256 must end with a trailing newline"
    assert not raw.endswith(b"\n\n"), "manifest.sha256 must have exactly one trailing newline"
    text = raw.decode("utf-8")
    lines = text.rstrip("\n").split("\n")
    assert lines, "manifest empty"
    names = []
    for line in lines:
        # Two ASCII spaces separate the digest from the basename.
        assert "  " in line, f"malformed manifest line: {line!r}"
        h, name = line.split("  ", 1)
        names.append(name)
        assert hashlib.sha256((OUT / name).read_bytes()).hexdigest() == h, f"digest mismatch for {name}"
    # Instruction L19: names in sorted order.
    assert names == sorted(names), f"manifest names not in sorted order: {names}"
    assert names == MANIFEST_NAMES, f"manifest coverage differs: got {names} vs {MANIFEST_NAMES}"


def _tool_round_trips():
    root = extracted_tool()
    cfg = OUT / "config.json"
    cfg.chmod(0o644)
    # 1. The repaired tool must validate the delivered config.
    result = run_tool("validate", "--schema", str(root / "schema.json"), "--config", str(cfg))
    assert result.returncode == 0, result.stderr or result.stdout
    assert result.stdout.strip() == "ok"
    # 2. Re-run compile via the delivered tool and byte-compare aggregates.json.
    #    compile reads config.json from --out, so we seed it from the agent's config.
    import tempfile as _tf, shutil as _sh
    scratch = Path(_tf.mkdtemp(prefix="roundtrip-out-"))
    scratch.chmod(0o777)
    _sh.copy2(cfg, scratch / "config.json")
    (scratch / "config.json").chmod(0o644)
    r2 = run_tool("compile", "--data", str(shipped_dir()), "--out", str(scratch))
    assert r2.returncode == 0, r2.stderr or r2.stdout
    delivered = (OUT / "aggregates.json").read_bytes()
    reproduced = (scratch / "aggregates.json").read_bytes()
    assert delivered == reproduced, "delivered aggregates.json does not match tool-re-produced bytes"

def _cli_repaired():
    root = extracted_tool()
    for sub in ("plan", "compile"):
        r = run_tool(sub, "--help")
        assert r.returncode == 0, (sub, r.stderr or r.stdout)
    _flat_dir = Path(tempfile.mkdtemp(prefix="cli-flat-"))
    _flat_dir.chmod(0o755)
    nested = _flat_dir / "nested.json"
    nested.write_text('{"profile":"X","nested":{"deep":1}}', encoding="utf-8")
    nested.chmod(0o644)
    r = run_tool("validate", "--schema", str(root / "schema.json"), "--config", str(nested))
    assert r.returncode != 0, "validator must reject nested"
    outdir = Path(tempfile.mkdtemp(prefix="cli-det-"))
    outdir.chmod(0o777)
    out_a = outdir / "a.json"
    out_b = outdir / "b.json"
    r1 = run_tool("init", "--schema", str(root / "schema.json"), "--out", str(out_a))
    r2 = run_tool("init", "--schema", str(root / "schema.json"), "--out", str(out_b))
    assert r1.returncode == 0 and r2.returncode == 0, (r1.stderr, r2.stderr)
    assert out_a.read_bytes() == out_b.read_bytes(), "init must be deterministic"


def _world_readable():
    # Owner-readable is the explicit guarantee the verifier needs; owner-only artefacts
    # (0600) are the agent's prerogative, so we only assert owner-read and regular-file.
    for name in ARTIFACTS:
        info = (OUT / name).stat()
        assert stat.S_ISREG(info.st_mode), name
        assert info.st_mode & stat.S_IRUSR, name


