def _zip_deterministic():
    """tool.zip must be deterministically rebuilt: ZIP_STORED compression,
    all member date_time values identical, all external_attr values identical, members sorted.
    Specific values are not required (instruction L18: 'fixed epoch, fixed external_attr' - not values)."""
    import zipfile as _zf
    z = _zf.ZipFile(OUT / "tool.zip")
    infos = z.infolist()
    assert infos, "empty tool.zip"
    names = [i.filename for i in infos]
    assert names == sorted(names), f"tool.zip members not sorted: {names}"
    first_dt = infos[0].date_time
    first_attr = infos[0].external_attr
    for info in infos:
        assert info.compress_type == _zf.ZIP_STORED, f"{info.filename}: compression != STORED"
        assert info.date_time == first_dt, f"{info.filename}: date_time varies ({info.date_time} vs {first_dt})"
        assert info.external_attr == first_attr, f"{info.filename}: external_attr varies ({oct(info.external_attr)} vs {oct(first_attr)})"

def _no_extra_artifacts():
    """OUT must contain exactly the declared ARTIFACTS, no extras."""
    present = {p.name for p in OUT.iterdir() if p.is_file()}
    expected = set(ARTIFACTS)
    extras = present - expected
    missing = expected - present
    assert not extras, f"extra files in /app/out: {sorted(extras)}"
    assert not missing, f"missing files from /app/out: {sorted(missing)}"

def _json_bytes_exact():
    """Every JSON artifact must be serialized with sort_keys=True, indent=2, separators=(',', ': '), ensure_ascii=False, trailing \n."""
    import json as _j
    for name in ARTIFACTS:
        if not name.endswith(".json"):
            continue
        raw = (OUT / name).read_bytes()
        try:
            obj = _j.loads(raw)
        except Exception as e:
            raise AssertionError(f"{name}: not parseable JSON ({e})")
        reserialized = _j.dumps(obj, sort_keys=True, indent=2, separators=(",", ": "), ensure_ascii=False).encode("utf-8") + b"\n"
        assert raw == reserialized, f"{name}: bytes do not match canonical serialization"

def _report_keys_exact():
    """report.json must carry EXACTLY ok/tool/config_path/config_sha256/trailer/commands, no extras."""
    allowed = {"ok", "tool", "config_path", "config_sha256", "trailer", "commands"}
    r = load("report.json")
    extras = set(r.keys()) - allowed
    missing = allowed - set(r.keys())
    assert not extras, f"report.json has extra keys: {sorted(extras)}"
    assert not missing, f"report.json missing keys: {sorted(missing)}"


@criterion(description="tool.zip is deterministically rebuilt (ZIP_STORED, fixed epoch, sorted members, 0100644).")
def zip_deterministic(workspace: Path) -> bool:
    return _holds(_zip_deterministic)


@criterion(description="/app/out contains exactly the declared artifacts, no extras.")
def no_extra_artifacts(workspace: Path) -> bool:
    return _holds(_no_extra_artifacts)


@criterion(description="Every JSON artifact uses the exact serialization bytes the contract names.")
def json_bytes_exact(workspace: Path) -> bool:
    return _holds(_json_bytes_exact)


@criterion(description="report.json carries exactly the allowed key set.")
def report_keys_exact(workspace: Path) -> bool:
    return _holds(_report_keys_exact)

